export function openSystemDetails(c){
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=c.id;const e=c.evidence;$('#detailKicker').textContent=e.screen;$('#detailTitle').textContent=c.source;$('#evidenceBody').innerHTML=`<div class="record-toolbar"><span>Reference <b>${esc(e.reference)}</b></span><span class="pill">MOCK SYSTEM RECORD</span></div><div class="detail-fields">${e.fields.map(([k,v])=>`<div><span>${esc(k)}</span><b class="${v==='FAILED'?'failed':''}">${esc(v)}</b></div>`).join('')}</div><div class="table-title">${id==='portal'?'Transaction history · October 2026':id==='mcc'?'Reference workbook · Matching rows':id==='policy'?'Programme eligibility checks':'Enquiry results'}</div><div class="table-scroll"><table><thead><tr>${e.columns.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${e.rows.map(row=>`<tr class="${row.includes('FAILED')?'failed-row':''}">${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${id==='portal'?'<div class="cap-summary"><div><small>Successful monthly credits</small><b>180,000 pts</b></div><div><small>Monthly cap</small><b>500,000 pts</b></div><div><small>Remaining allowance</small><b>320,000 pts</b></div></div>':''}<div class="detail-conclusion ${c.warn?'alert':''}"><small>CONCLUSION</small><p>${esc(e.conclusion)}</p></div>${e.note?`<p class="fine">${esc(e.note)}</p>`:''}<p class="fine">Fabricated screen and records for demonstration; no connection to the source system.</p>`;$('#evidence').showModal();}
